package opencode

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

func TestOpenCodeAgent_Identity(t *testing.T) {
	t.Parallel()

	ag := &OpenCodeAgent{}

	if ag.Name() != agent.AgentNameOpenCode {
		t.Errorf("expected name %q, got %q", agent.AgentNameOpenCode, ag.Name())
	}
	if ag.Type() != agent.AgentTypeOpenCode {
		t.Errorf("expected type %q, got %q", agent.AgentTypeOpenCode, ag.Type())
	}
	if ag.Description() == "" {
		t.Error("expected non-empty description")
	}
	if !ag.SupportsHooks() {
		t.Error("expected SupportsHooks() == true")
	}
}

func TestOpenCodeAgent_ProtectedDirs(t *testing.T) {
	t.Parallel()

	ag := &OpenCodeAgent{}
	dirs := ag.ProtectedDirs()

	if len(dirs) != 1 || dirs[0] != ".opencode" {
		t.Errorf("expected [.opencode], got %v", dirs)
	}
}

func TestOpenCodeAgent_DetectPresence_OpenCodeDir(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	// No .opencode directory
	ag := &OpenCodeAgent{}
	found, err := ag.DetectPresence()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if found {
		t.Error("expected DetectPresence to be false without .opencode")
	}

	// Create .opencode directory
	if err := os.Mkdir(filepath.Join(dir, ".opencode"), 0o750); err != nil {
		t.Fatalf("failed to create .opencode: %v", err)
	}

	found, err = ag.DetectPresence()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !found {
		t.Error("expected DetectPresence to be true with .opencode")
	}
}

func TestOpenCodeAgent_DetectPresence_OpencodeJSON(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	ag := &OpenCodeAgent{}

	// Create opencode.json
	if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte("{}"), 0o600); err != nil {
		t.Fatalf("failed to create opencode.json: %v", err)
	}

	found, err := ag.DetectPresence()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !found {
		t.Error("expected DetectPresence to be true with opencode.json")
	}
}

func TestOpenCodeAgent_ReadTranscript(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	transcriptPath := filepath.Join(dir, "transcript.jsonl")
	content := `{"type":"user","message":{"role":"user","content":"hello"}}` + "\n"
	if err := os.WriteFile(transcriptPath, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	ag := &OpenCodeAgent{}
	data, err := ag.ReadTranscript(transcriptPath)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if string(data) != content {
		t.Errorf("expected transcript content to match")
	}
}

func TestOpenCodeAgent_ReadTranscript_NotFound(t *testing.T) {
	t.Parallel()

	ag := &OpenCodeAgent{}
