package opencode

import (
	"os"
	"path/filepath"
	"testing"
)

func TestInstallHooks_CreatesPluginFile(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	// Initialize a git repo so paths.RepoRoot() works
	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}
	count, err := ag.InstallHooks(false, false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if count == 0 {
		t.Error("expected hooks to be installed")
	}

	// Verify plugin file was created
	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
	data, err := os.ReadFile(pluginPath)
	if err != nil {
		t.Fatalf("plugin file not created: %v", err)
	}

	// Check it contains the production command
	content := string(data)
	if !contains(content, `"entire"`) {
		t.Error("expected plugin to contain 'entire' command")
	}
	if contains(content, "go run") {
		t.Error("expected production mode, but found go run prefix")
	}
}

func TestInstallHooks_LocalDev(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}
	count, err := ag.InstallHooks(true, false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if count == 0 {
		t.Error("expected hooks to be installed")
	}

	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
	data, err := os.ReadFile(pluginPath)
	if err != nil {
		t.Fatalf("plugin file not created: %v", err)
	}

	if !contains(string(data), "go run") {
		t.Error("expected local dev mode to use go run prefix")
	}
}

func TestInstallHooks_Idempotent(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}

	// First install
	count1, err := ag.InstallHooks(false, false)
	if err != nil {
		t.Fatalf("first install error: %v", err)
	}
	if count1 == 0 {
		t.Error("expected hooks installed on first call")
	}

	// Second install should be idempotent
	count2, err := ag.InstallHooks(false, false)
	if err != nil {
		t.Fatalf("second install error: %v", err)
	}
	if count2 != 0 {
		t.Errorf("expected 0 new hooks on second install, got %d", count2)
	}
}

func TestInstallHooks_ForceReinstall(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}

	// First install
	if _, err := ag.InstallHooks(false, false); err != nil {
		t.Fatalf("first install error: %v", err)
	}

	// Force reinstall
	count, err := ag.InstallHooks(false, true)
	if err != nil {
		t.Fatalf("force install error: %v", err)
	}
	if count == 0 {
		t.Error("expected hooks reinstalled with force")
	}
}

func TestUninstallHooks(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}

	// Install first
	if _, err := ag.InstallHooks(false, false); err != nil {
		t.Fatalf("install error: %v", err)
	}

	// Verify installed
	if !ag.AreHooksInstalled() {
		t.Error("expected hooks to be installed")
	}

	// Uninstall
	if err := ag.UninstallHooks(); err != nil {
		t.Fatalf("uninstall error: %v", err)
	}

	// Verify uninstalled
	if ag.AreHooksInstalled() {
		t.Error("expected hooks to be uninstalled")
	}
}

func TestAreHooksInstalled_NoFile(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)

	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o750); err != nil {
		t.Fatalf("failed to create .git: %v", err)
	}

	ag := &OpenCodeAgent{}
	if ag.AreHooksInstalled() {
		t.Error("expected hooks not installed when no plugin file exists")
	}
}

func TestGetSupportedHooks(t *testing.T) {
	t.Parallel()

	ag := &OpenCodeAgent{}
	hooks := ag.GetSupportedHooks()
	if len(hooks) == 0 {
		t.Error("expected non-empty supported hooks")
	}
}

func TestGetHookNames(t *testing.T) {
	t.Parallel()

	ag := &OpenCodeAgent{}
	names := ag.GetHookNames()

	if len(names) != 6 {
		t.Errorf("expected 6 hook names, got %d", len(names))
	}
